#
# classify-canon-outcome.sh <код-возврата-make> <файл-с-выводом>
#
# Различает исходы сверки канона модели доступов и печатает свой вердикт:
#
#   0  — сверено ЛИБО «условие не создано»: вердикта о совпадении блоков нет,
#        и это не дефект дерева;
#   1  — КРАСНОЕ: блоки разошлись с манифестами, в дереве есть что чинить;
#   2  — исход НЕ РАЗОБРАН: исполнитель вышел ненулевым и не назвал себя ни
#        одной строкой-маркером. О блоках не сказано ничего.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОЧЕМУ ПО ТЕКСТУ, А НЕ ПО КОДУ — ЭТО ЗАМЕР, А НЕ ОСТОРОЖНОСТЬ
#
# `make` СХЛОПЫВАЕТ код рецепта в свой собственный: исполнитель, вышедший 1
# (находка), 2 (сверять нечего) и 3 (проверка не исполнялась), одинаково доезжает
# до оболочки ДВОЙКОЙ. Проверено прогоном: make печатает «Ошибка 3» и выходит
# кодом 2.
#
# Прежняя редакция шага разбирала именно код, и двойка означала у неё «условие не
# создано, exit 0». То есть НАСТОЯЩЕЕ РАСХОЖДЕНИЕ БЛОКОВ — лишнее право в модели
# либо отказ там, где доступ выдан — доезжало до ствола ЗЕЛЁНЫМ, с заголовком о
# несозданном условии. Класс тот же, что у соседа `catalogparity`, и там он был
# закрыт раньше.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОРЯДОК РАЗБОРА НЕСУЩИЙ
#
# Находка спрашивается ПЕРВОЙ. Текст «условие не создано» поминает находки
# словом («все 5 находки — ровно об их отсутствии»), и обратный порядок глотал бы
# красное — то есть возвращал бы ровно тот дефект, ради которого файл написан.
#
# Маркер находки привязан к НАЧАЛУ СТРОКИ (`^НАХОДКА:`): так его печатает сам
# исполнитель, и та же буква внутри прозы вердиктом не становится.
set -uo pipefail

readonly FINDING_RE='^НАХОДКА:'
readonly VOID_RE='НЕ ИСПОЛНЯЛАСЬ|УСЛОВИЕ НЕ СОЗДАНО|сверять нечего'

classify() {
    local rc="$1" log="$2"
    if [ ! -r "$log" ]; then
        echo "канон модели: вывод исполнителя не прочитан ($log) — исход НЕ РАЗОБРАН" >&2
        return 2
    fi
    if [ "$rc" -eq 0 ]; then
        echo "канон модели: блоки сверены (код make 0)"
        return 0
    fi
    if grep -qE "$FINDING_RE" "$log"; then
        echo "канон модели: КРАСНОЕ — блоки разошлись с манифестами." >&2
        echo "Лишняя строка в модели есть лишнее право, недостающая — отказ там, где доступ выдан." >&2
        return 1
    fi
    if grep -qE "$VOID_RE" "$log"; then
        echo "канон модели: УСЛОВИЕ НЕ СОЗДАНО — сверка НЕ ИСПОЛНЯЛАСЬ." >&2
        echo "Вердикта о совпадении блоков нет ни зелёного, ни красного; текст выше называет," >&2
        echo "чего не хватило. Это не дефект дерева и не успех." >&2
        return 0
    fi
    echo "канон модели: исход НЕ РАЗОБРАН — исполнитель вышел кодом $rc и не назвал себя" >&2
    echo "ни одной строкой-маркером. О блоках модели не сказано НИЧЕГО." >&2
    return 2
}

# --- самопроверка: доказательство инъекцией в обе стороны ---------------------
#
# Живёт ФЛАГОМ этого же файла, а не соседним: отдельный файл в перечень шагов
# конвейера не попал бы сам, то есть не исполнялся бы никогда.
if [ "${1:-}" = "--self-test" ]; then
    TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
    probes=0; failed=0
    run() { # run <ожидаемый-код> <имя> <код-make> <тело-вывода>
        local want="$1" name="$2" rc="$3" body="$4" got=0
        probes=$((probes + 1))
        printf '%s\n' "$body" > "$TMP/log"
        classify "$rc" "$TMP/log" >/dev/null 2>&1 || got=$?
        if [ "$got" -ne "$want" ]; then
            echo "  ПРОВАЛ $name — ждали $want, получили $got" >&2
            failed=$((failed + 1)); return
        fi
        echo "  ok   $name (код $got)"
    }

    # Тела взяты у самого исполнителя ДОСЛОВНО: синтетика доказывала бы, что
    # разбор понимает синтетику.
    finding=$'перепись: модулей набора 6 · манифестов найдено 5\nНАХОДКА: модуль vpc: модуль закрытого набора без манифеста и без записи ведомости: блоки канона этого модуля остались бы непрочитанными при зелёном вердикте\nmake: *** [Makefile:345: model-canon-check] Ошибка 1'
    notrun=$'перепись: модулей набора 6 · манифестов найдено 1\nНЕ ИСПОЛНЯЛАСЬ: условие сверки НЕ СОЗДАНО: дома манифестов соседних модулей (каталога services/) в обходе НЕТ, а все 5 находки — ровно об их отсутствии\nmake: *** [Makefile:345: model-canon-check] Ошибка 3'
    unmet=$'УСЛОВИЕ НЕ СОЗДАНО: цель model-canon-check сверяет ДВА дерева, а второго рядом нет.\nmake: *** [Makefile:344: model-canon-check] Ошибка 2'
    void=$'сверять нечего ни для одного модуля — это НЕ успех, а «проверять нечего»\nmake: *** [Makefile:345: model-canon-check] Ошибка 2'

    echo "=== разбор исхода сверки канона: доказательство инъекцией ==="
    # (−) ПОЛОЖИТЕЛЬНЫЙ БЛИЗНЕЦ: без него всё нижеследующее зеленело бы на
    # разборе, который краснеет всегда.
    run 0 "(−) код make 0 — сверено" 0 $'перепись: … блоков сверено 27 из 27'
    # (+) ГЛАВНЫЙ КЛАСС: находка доезжает КРАСНЫМ, хотя make схлопнул её в двойку.
    run 1 "(+) находка при коде make 2 — КРАСНОЕ, а не «условие не создано»" 2 "$finding"
    # (−) третья категория остаётся третьей и в зелёное не вырождается по коду 0
    #     шага: вердикта нет, и это НАЗВАНО.
    run 0 "(−) «не исполнялась» — шаг не роняется" 2 "$notrun"
    run 0 "(−) второго дерева нет — шаг не роняется" 2 "$unmet"
    run 0 "(−) сверять нечего — шаг не роняется" 2 "$void"
    # (+) ПОРЯДОК: текст «условие не создано» поминает находки словом. Обратный
    #     порядок разбора проглотил бы красное, и эта проба его ловит.
    run 1 "(+) находка И текст о несозданном условии разом — побеждает находка" 2 \
        "$notrun"$'\n'"$finding"
    # (+) исход не назван ни одной строкой — НЕ РАЗОБРАНО, а не «чисто».
    run 2 "(+) ненулевой код без маркера — исход НЕ РАЗОБРАН" 2 $'сегфолт\nничего не сказано'
    run 2 "(+) вывода нет вовсе — исход НЕ РАЗОБРАН" 2 ""
    # (+) вывод не прочитан — тоже не «чисто».
    probes=$((probes + 1)); got=0
    classify 2 "$TMP/нет-такого-файла" >/dev/null 2>&1 || got=$?
    if [ "$got" -ne 2 ]; then
        echo "  ПРОВАЛ (+) вывод недоступен — ждали 2, получили $got" >&2
        failed=$((failed + 1))
    else
        echo "  ok   (+) вывод недоступен — исход НЕ РАЗОБРАН (код 2)"
    fi

    echo
    echo "classify-canon-outcome --self-test: проб исполнено $probes, провалов $failed"
    [ "$probes" -eq 0 ] && { echo "ПРОВАЛ: ни одной пробы не исполнено" >&2; exit 2; }
    [ "$failed" -gt 0 ] && exit 1
    exit 0
fi

if [ "$#" -ne 2 ]; then
    echo "нужно два довода: <код-возврата-make> <файл-с-выводом>" >&2
    exit 2
fi
classify "$1" "$2"
